  "dependencies": {
    "commander": "^12.1.0",
    "gray-matter": "^4.0.3",
    "marked": "^12.0.2"
  }
}

export interface PageFrontmatter {
  title?: string;
  date?: string;
  tags?: string[] | string;
  [key: string]: unknown;
}

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
  outputPath: string;
}

import matter from 'gray-matter';

export interface FrontmatterResult {
  data: Record<string, unknown>;
  content: string;
}

const FRONTMATTER_BLOCK = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;

function parseScalar(raw: string): unknown {
  const trimmed = raw.trim();
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed !== '' && !Number.isNaN(Number(trimmed))) return Number(trimmed);
  return trimmed;
}

function parseValue(key: string, raw: string): unknown {
  const trimmed = raw.trim();
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    const inner = trimmed.slice(1, -1).trim();
    if (!inner) return [];
    return inner.split(',').map((item) => parseScalar(item));
  }
  if (key === 'tags' && trimmed.includes(',')) {
    return trimmed.split(',').map((item) => parseScalar(item));
  }
  return parseScalar(trimmed);
}

/**
 * Splits a `---`-delimited YAML frontmatter block into key: value pairs.
 * Only flat scalar/array values are supported (no nested maps).
 */
function parseSimpleYaml(block: string): Record<string, unknown> {
  const data: Record<string, unknown> = {};
  for (const line of block.split(/\r?\n/)) {
    const trimmedLine = line.trim();
    if (!trimmedLine || trimmedLine.startsWith('#')) continue;
    const separatorIndex = trimmedLine.indexOf(':');
    if (separatorIndex === -1) continue;
    const key = trimmedLine.slice(0, separatorIndex).trim();
    const rawValue = trimmedLine.slice(separatorIndex + 1);
    if (!key) continue;
    data[key] = parseValue(key, rawValue);
  }
  return data;
}

/**
 * Parses frontmatter from raw Markdown source. gray-matter only understands
 * JSON frontmatter here, so the `---`-delimited YAML block is additionally
 * parsed by hand and merged over gray-matter's output.
 */
export function parseFrontmatter(raw: string): FrontmatterResult {
  const parsed = matter(raw);
  const match = raw.match(FRONTMATTER_BLOCK);
  const yamlData = match ? parseSimpleYaml(match[1]) : {};
  return {
    data: { ...parsed.data, ...yamlData },
    content: parsed.content,
  };
}

import { marked } from 'marked';

export function renderMarkdown(content: string): string {
  return marked.parse(content, { async: false }) as string;
}

import { Page } from './types';

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export interface PageTemplateData {
  title: string;
  date?: string;
  tags: string[];
  body: string;
}

export function renderPageTemplate(data: PageTemplateData): string {
  const { title, date, tags, body } = data;
  const dateHtml = date ? `<p class="date">${escapeHtml(date)}</p>\n` : '';
  const tagsHtml = tags.length
    ? `<ul class="tags">${tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>\n`
    : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${escapeHtml(title)}</title>
</head>
<body>
<article>
<h1>${escapeHtml(title)}</h1>
${dateHtml}${tagsHtml}${body}
</article>
</body>
</html>
`;
}

export function renderIndexTemplate(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const dateHtml = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `<li><a href="${page.outputPath}">${escapeHtml(page.title)}</a>${dateHtml}</li>`;
    })
    .join('\n');
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Index</title>
</head>
<body>
<h1>All Pages</h1>
<ul class="page-list">
${items}
</ul>
</body>
</html>
`;
}

import fs from 'fs';
import path from 'path';
import { parseFrontmatter } from './frontmatter';
import { renderMarkdown } from './markdown';
import { renderIndexTemplate, renderPageTemplate } from './templates';
import { Page } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

function slugify(filename: string): string {
  return filename.replace(/\.md$/i, '');
}

function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) return tags.map((tag) => String(tag));
  if (typeof tags === 'string' && tags.length > 0) return [tags];
  return [];
}

export function findMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }
  return fs
    .readdirSync(contentDir)
    .filter((file) => file.toLowerCase().endsWith('.md'))
    .sort();
}

export function buildPage(contentDir: string, filename: string): Page {
  const filePath = path.join(contentDir, filename);
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = parseFrontmatter(raw);
  const body = renderMarkdown(content);
  const slug = slugify(filename);
  const title = typeof data.title === 'string' && data.title.length > 0 ? data.title : slug;
  const date = typeof data.date === 'string' ? data.date : undefined;
  const tags = normalizeTags(data.tags);
  const outputPath = `${slug}.html`;
  const html = renderPageTemplate({ title, date, tags, body });
  return { slug, title, date, tags, html, outputPath };
}

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const files = findMarkdownFiles(contentDir);
  const pages = files.map((file) => buildPage(contentDir, file));

  fs.mkdirSync(outputDir, { recursive: true });
  for (const page of pages) {
    fs.writeFileSync(path.join(outputDir, page.outputPath), page.html, 'utf-8');
  }
  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndexTemplate(pages), 'utf-8');

  return { pages, outputDir };
}

#!/usr/bin/env node
import path from 'path';
import { Command } from 'commander';
import { build } from './build';

const program = new Command();

program.name('ssg').description('A minimal static site generator');

program
  .command('build')
  .description('Generate the static site')
  .option('--content <dir>', 'content directory', './content')
  .option('--output <dir>', 'output directory', './dist')
  .action((opts: { content: string; output: string }) => {
    const contentDir = path.resolve(process.cwd(), opts.content);
    const outputDir = path.resolve(process.cwd(), opts.output);
    const result = build({ contentDir, outputDir });
    console.log(`Built ${result.pages.length} page(s) into ${outputDir}`);
  });

if (require.main === module) {
  program.parse(process.argv);
}

export { program };

export * from './build';
export * from './frontmatter';
export * from './markdown';
export * from './types';

import { parseFrontmatter } from '../src/frontmatter';

describe('parseFrontmatter', () => {
  it('parses YAML-style key: value frontmatter', () => {
    const raw = `---
title: Hello World
date: 2024-01-15
tags: [intro, news]
---
# Body

Some content.`;
    const { data, content } = parseFrontmatter(raw);
    expect(data.title).toBe('Hello World');
    expect(data.date).toBe('2024-01-15');
    expect(data.tags).toEqual(['intro', 'news']);
    expect(content.trim()).toBe('# Body\n\nSome content.');
  });

  it('supports comma-separated tags without brackets', () => {
    const raw = `---
title: Post
tags: a, b, c
---
Body text`;
    const { data } = parseFrontmatter(raw);
    expect(data.tags).toEqual(['a', 'b', 'c']);
  });

  it('supports quoted string values', () => {
    const raw = `---
title: "Quoted Title"
---
Body`;
    const { data } = parseFrontmatter(raw);
    expect(data.title).toBe('Quoted Title');
  });

  it('returns empty data and full content when there is no frontmatter', () => {
    const raw = `# Just Markdown\n\nNo frontmatter here.`;
    const { data, content } = parseFrontmatter(raw);
    expect(data).toEqual({});
    expect(content).toBe(raw);
  });

  it('merges JSON frontmatter handled by gray-matter with the YAML block', () => {
    const raw = `---
title: From YAML
---
Body`;
    const { data } = parseFrontmatter(raw);
    expect(data.title).toBe('From YAML');
  });
});

import { renderMarkdown } from '../src/markdown';

describe('renderMarkdown', () => {
  it('converts headings to HTML', () => {
    const html = renderMarkdown('# Hello');
    expect(html).toContain('<h1>Hello</h1>');
  });

  it('converts paragraphs and emphasis to HTML', () => {
    const html = renderMarkdown('This is **bold** and *italic*.');
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<em>italic</em>');
  });

  it('converts lists to HTML', () => {
    const html = renderMarkdown('- one\n- two');
    expect(html).toContain('<ul>');
    expect(html).toContain('<li>one</li>');
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { build, buildPage, findMarkdownFiles } from '../src/build';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('static site build', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir('ssg-content-');
    outputDir = makeTmpDir('ssg-dist-');
    fs.writeFileSync(
      path.join(contentDir, 'first-post.md'),
      `---
title: First Post
date: 2024-01-01
tags: [intro, news]
---
# Hello

This is the **first** post.`
    );
    fs.writeFileSync(
      path.join(contentDir, 'second-post.md'),
      `---
title: Second Post
date: 2024-02-01
tags: update
---
Some more content here.`
    );
    fs.writeFileSync(path.join(contentDir, 'no-frontmatter.md'), '# No Frontmatter\n\nJust text.');
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('finds all markdown files in the content directory, sorted', () => {
    const files = findMarkdownFiles(contentDir);
    expect(files).toEqual(['first-post.md', 'no-frontmatter.md', 'second-post.md']);
  });

  it('throws when the content directory does not exist', () => {
    expect(() => findMarkdownFiles(path.join(contentDir, 'missing'))).toThrow(/Content directory not found/);
  });

  it('builds a single page with frontmatter applied', () => {
    const page = buildPage(contentDir, 'first-post.md');
    expect(page.title).toBe('First Post');
    expect(page.date).toBe('2024-01-01');
    expect(page.tags).toEqual(['intro', 'news']);
    expect(page.outputPath).toBe('first-post.html');
    expect(page.html).toContain('<h1>First Post</h1>');
    expect(page.html).toContain('<strong>first</strong>');
  });

  it('falls back to the filename slug as title when frontmatter has none', () => {
    const page = buildPage(contentDir, 'no-frontmatter.md');
    expect(page.title).toBe('no-frontmatter');
    expect(page.html).toContain('<h1>No Frontmatter</h1>');
  });

  it('normalizes a single string tag into an array', () => {
    const page = buildPage(contentDir, 'second-post.md');
    expect(page.tags).toEqual(['update']);
  });

  it('writes an HTML file per page plus an index.html to the output directory', () => {
    const result = build({ contentDir, outputDir });
    expect(result.pages).toHaveLength(3);

    const distFiles = fs.readdirSync(outputDir).sort();
    expect(distFiles).toEqual(
      ['first-post.html', 'index.html', 'no-frontmatter.html', 'second-post.html'].sort()
    );

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(indexHtml).toContain('First Post');
    expect(indexHtml).toContain('Second Post');
    expect(indexHtml).toContain('href="first-post.html"');
  });

  it('creates the output directory if it does not exist', () => {
    const nestedOutput = path.join(outputDir, 'nested', 'dist');
    build({ contentDir, outputDir: nestedOutput });
    expect(fs.existsSync(path.join(nestedOutput, 'index.html'))).toBe(true);
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { program } from '../src/cli';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('ssg CLI', () => {
  let contentDir: string;
  let outputDir: string;
  let logSpy: jest.SpyInstance;

  beforeEach(() => {
    contentDir = makeTmpDir('ssg-cli-content-');
    outputDir = makeTmpDir('ssg-cli-dist-');
    fs.writeFileSync(
      path.join(contentDir, 'page.md'),
      `---
title: CLI Page
date: 2024-03-01
---
Hello from the CLI test.`
    );
    logSpy = jest.spyOn(console, 'log').mockImplementation(() => undefined);
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
    logSpy.mockRestore();
  });

  it('builds the site using --content and --output flags', () => {
    program.parse(['node', 'ssg', 'build', '--content', contentDir, '--output', outputDir]);

    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
    const pageHtml = fs.readFileSync(path.join(outputDir, 'page.html'), 'utf-8');
    expect(pageHtml).toContain('CLI Page');
    expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('Built 1 page(s)'));
  });

  it('defaults to ./content and ./dist when no options are given', () => {
    const cwdSpy = jest.spyOn(process, 'cwd').mockReturnValue(contentDir);
    fs.mkdirSync(path.join(contentDir, 'content'));
    fs.writeFileSync(path.join(contentDir, 'content', 'only.md'), '# Only Page');

    program.parse(['node', 'ssg', 'build']);

    expect(fs.existsSync(path.join(contentDir, 'dist', 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(contentDir, 'dist', 'only.html'))).toBe(true);

    cwdSpy.mockRestore();
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawnSync } from 'child_process';

const CLI_ENTRY = path.join(__dirname, '..', 'src', 'cli.ts');
const TS_NODE_REGISTER = require.resolve('ts-node/register/transpile-only');

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function runCli(args: string[], cwd: string) {
  return spawnSync(process.execPath, ['-r', TS_NODE_REGISTER, CLI_ENTRY, ...args], {
    cwd,
    encoding: 'utf-8',
  });
}

describe('ssg CLI', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir('ssg-cli-content-');
    outputDir = makeTmpDir('ssg-cli-dist-');
    fs.writeFileSync(
      path.join(contentDir, 'page.md'),
      `---
title: CLI Page
date: 2024-03-01
---
Hello from the CLI test.`
    );
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('builds the site using --content and --output flags', () => {
    const result = runCli(['build', '--content', contentDir, '--output', outputDir], process.cwd());

    expect(result.status).toBe(0);
    expect(result.stdout).toContain('Built 1 page(s)');
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
    const pageHtml = fs.readFileSync(path.join(outputDir, 'page.html'), 'utf-8');
    expect(pageHtml).toContain('CLI Page');
  }, 20000);

  it('defaults to ./content and ./dist relative to the current working directory', () => {
    const workDir = makeTmpDir('ssg-cli-cwd-');
    fs.mkdirSync(path.join(workDir, 'content'));
    fs.writeFileSync(path.join(workDir, 'content', 'only.md'), '# Only Page');

    const result = runCli(['build'], workDir);

    expect(result.status).toBe(0);
    expect(fs.existsSync(path.join(workDir, 'dist', 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(workDir, 'dist', 'only.html'))).toBe(true);

    fs.rmSync(workDir, { recursive: true, force: true });
  }, 20000);

  it('exits with an error when the content directory is missing', () => {
    const result = runCli(['build', '--content', path.join(contentDir, 'missing'), '--output', outputDir], process.cwd());

    expect(result.status).not.toBe(0);
    expect(result.stderr).toContain('Content directory not found');
  }, 20000);
});

